mapper.update:
UPDATE gateway_wiki_page SET deleted_at = (CURRENT_TIMESTAMP AT TIME ZONE 'UTC'), version = version + 1,
    update_user_id = #{et.updateUserId}, update_time = #{et.updateTime,jdbcType=TIMESTAMP}
WHERE id = #{et.id} AND tenant_id = #{et.tenantId} AND deleted_at IS NULL AND version = #{MP_OPTLOCK_VERSION_ORIGINAL}

UPDATE gateway_wiki_page SET draft_revision_id = #{et.draftRevisionId,jdbcType=BIGINT},
    published_revision_id = #{et.publishedRevisionId,jdbcType=BIGINT},
    revision = #{et.revision}, version = version + 1,
    update_user_id = #{actorUserId}, update_time = #{now,jdbcType=TIMESTAMP}
WHERE id = #{et.id} AND tenant_id = #{et.tenantId} AND kb_id = #{et.kbId} AND slug = #{et.slug}
    AND revision = #{expectedRevision}
    AND (published_revision_id = #{expectedPublishedRevisionId,jdbcType=BIGINT}
        OR (published_revision_id IS NULL AND #{expectedPublishedRevisionId,jdbcType=BIGINT} IS NULL))
    AND (draft_revision_id = #{expectedDraftRevisionId,jdbcType=BIGINT}
        OR (draft_revision_id IS NULL AND #{expectedDraftRevisionId,jdbcType=BIGINT} IS NULL))
    AND deleted_at IS NULL AND version = #{et.version}

mapper.sql:
AND p.kb_id = #{kbId}

    AND (p.slug ILIKE #{searchPattern} ESCAPE '\' OR v.title ILIKE #{searchPattern} ESCAPE '\')


    AND v.tags @> jsonb_build_array(CAST(#{tag} AS TEXT))

mapper.select:
SELECT p.id, p.tenant_id, p.create_user_id, p.create_time, p.update_user_id, p.update_time, p.deleted_at, p.version, p.kb_id, p.slug, p.draft_revision_id, p.published_revision_id, p.revision
WHERE p.deleted_at IS NULL
ORDER BY p.create_time DESC, p.id DESC LIMIT #{limit} OFFSET #{offset}
